let topic = db.topics.findOne({ subject: "french", title: TOPIC_TITLE, parentId: PARENT });
if (!topic) {
  if (DRYRUN) {
    print("DRYRUN: wuerde Topic '" + TOPIC_TITLE + "' als Kind von " + PARENT + " anlegen");
  } else {
    const r = db.topics.insertOne({
      subject: "french",
      title: TOPIC_TITLE,
      tutorial: "",
      quiz: QUIZ,
      user: USER,
      parentId: PARENT,
      createdAt: new Date(),
      updatedAt: new Date(),
    });
    topic = db.topics.findOne({ _id: r.insertedId });
    print("Topic angelegt: " + topic._id);
  }
} else {
  print("Topic existiert: " + topic._id);
}

let inserted = 0, skipped = 0;
for (const d of raw) {
  const exists = db.exercises.countDocuments({ topic: topic ? topic._id : null, gapText: d.gapText }) > 0;
  if (topic && exists) { skipped++; continue; }
  if (DRYRUN) {
    if (inserted === 0) print("DRYRUN - Beispiele:");
    if (inserted < 5) print("  n=" + d.n + " img=" + (d.imageUrl ? "JA" : "nein") + " " + d.gapText.slice(0, 90));
    inserted++;
    continue;
  }
  db.exercises.insertOne({
    quiz: QUIZ,
    subject: d.subject,
    type: d.type,
    imageUrl: d.imageUrl,
    topic: topic._id,
    school: SCHOOL,
    user: USER,
    instruction: d.instruction,
    gapText: d.gapText,
    options: [],
    optionsEn: [],
    optionsFr: [],
    createdAt: new Date(),
    updatedAt: new Date(),
    __v: 0,
  });
  inserted++;
}
print((DRYRUN ? "DRYRUN: wuerde " : "Eingefuegt: ") + inserted + " Uebungen, " + skipped + " uebersprungen (existieren bereits)");
if (!DRYRUN) {
  const total = db.exercises.countDocuments({ topic: topic._id, type: "gapText" });
  print("Im Topic jetzt " + total + " gapText-Uebungen");
}
